import{_ as e,o as a,c as t,ag as l}from"./chunks/framework.CtWPcAmt.js";const u=JSON.parse('{"title":"第 22 章：软件与项目搭建案例——从零到可发布的教程仓库","description":"用本书仓库的真实搭建过程演示项目类任务：需求、框架、基准、实测、界面文档、评分、合并发布；重点展示项目规则与验证流程。","frontmatter":{"title":"第 22 章：软件与项目搭建案例——从零到可发布的教程仓库","description":"用本书仓库的真实搭建过程演示项目类任务：需求、框架、基准、实测、界面文档、评分、合并发布；重点展示项目规则与验证流程。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/22-software-project-case.md","filePath":"guide/22-software-project-case.md","lastUpdated":null}'),i={name:"guide/22-software-project-case.md"};function r(s,o,n,d,c,g){return a(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="第-22-章-软件与项目搭建案例——从零到可发布的教程仓库" tabindex="-1">第 22 章：软件与项目搭建案例——从零到可发布的教程仓库 <a class="header-anchor" href="#第-22-章-软件与项目搭建案例——从零到可发布的教程仓库" aria-label="Permalink to &quot;第 22 章：软件与项目搭建案例——从零到可发布的教程仓库&quot;">​</a></h1><h2 id="案例摘要" tabindex="-1">案例摘要 <a class="header-anchor" href="#案例摘要" aria-label="Permalink to &quot;案例摘要&quot;">​</a></h2><ul><li>使用场景：软件与项目搭建</li><li>使用者基础：能完成第 7–18 章学习（不要求编程，但要求按步骤操作）</li><li>使用的 Agent：桌面 Agent（Codex 等，本项目实际使用） + 视觉模型辅助</li><li>完成时间：约两周（跨多个阶段）</li><li>风险等级：中（涉及 git、版本控制、发布）</li><li>最终交付物：公开 GitHub 仓库（23 章教程 + 实测数据 + 截图 + 文档）</li></ul><h2 id="任务背景" tabindex="-1">任务背景 <a class="header-anchor" href="#任务背景" aria-label="Permalink to &quot;任务背景&quot;">​</a></h2><p>教程内容规划好后（第 21 章），需要一个「能放内容、能协作、能发布」的项目仓库，并把「七款产品实测」这个研究任务也纳入项目管理——实测数据要归档、截图要规范、结论要可回查。这是一个典型的软件项目搭建任务：<strong>内容工程 + 数据归档 + 版本管理</strong>。</p><h2 id="原始需求" tabindex="-1">原始需求 <a class="header-anchor" href="#原始需求" aria-label="Permalink to &quot;原始需求&quot;">​</a></h2><blockquote><p>「建一个教程仓库，把章节、素材、实测数据都放进去，并且能管理好版本。」</p></blockquote><h2 id="任务判断" tabindex="-1">任务判断 <a class="header-anchor" href="#任务判断" aria-label="Permalink to &quot;任务判断&quot;">​</a></h2><ul><li>为什么适合 Agent：目录/文件操作、批量整理、数据汇总、重复性文档工作；</li><li>交给 Agent：建目录骨架、批量格式化、基准测试执行、界面文档撰写、评分数据整理；</li><li>人必须做的：架构决策（章节结构）、验收（每阶段）、git 关键操作确认、发布决策。</li></ul><h2 id="整理后的任务卡-阶段一-框架搭建" tabindex="-1">整理后的任务卡（阶段一：框架搭建） <a class="header-anchor" href="#整理后的任务卡-阶段一-框架搭建" aria-label="Permalink to &quot;整理后的任务卡（阶段一：框架搭建）&quot;">​</a></h2><ul><li><strong>目标</strong>：建立 23 章教程的仓库骨架；</li><li><strong>上下文</strong>：面向零基础读者；中国版产品只用中国站资料；</li><li><strong>输入材料</strong>：教程规划文档（<code>docs/00-06</code>）；</li><li><strong>范围与约束</strong>：只创建新文件，不删除既有内容；目录按规划命名；</li><li><strong>交付物</strong>：仓库结构 + README + docs/ 系列规范文档；</li><li><strong>验收标准</strong>：目录与规划一致；每份规范文档有明确职责；无内容缺失。</li></ul><h2 id="执行过程-六个阶段" tabindex="-1">执行过程（六个阶段） <a class="header-anchor" href="#执行过程-六个阶段" aria-label="Permalink to &quot;执行过程（六个阶段）&quot;">​</a></h2><ol><li><strong>框架搭建</strong>：建仓库、23 章目录、规范文档（<code>docs/00-06</code>）、模板（<code>templates/</code>）；</li><li><strong>定价调研</strong>：核对七款产品中国版价格与福利，产出 <code>docs/07</code>（易变信息集中管理）；</li><li><strong>本机界面核对</strong>：安装版本、界面形态记录（<code>docs/09</code>）；</li><li><strong>基准实测</strong>：设计统一任务（<code>docs/08</code>）→ 七款产品实测 → 数据归档（<code>research/runs/</code>）；</li><li><strong>截图与界面讲解</strong>：18 张截图 → 视觉模型分析 → 7 份界面讲解文档（<code>docs/11-interface-guides/</code>）；</li><li><strong>评分与正文</strong>：六维评分（<code>docs/12</code>）→ 产品页（第 5 章）→ 选择矩阵（<code>docs/10</code>）→ 第 6 章。</li></ol><h2 id="出现的问题-真实记录" tabindex="-1">出现的问题（真实记录） <a class="header-anchor" href="#出现的问题-真实记录" aria-label="Permalink to &quot;出现的问题（真实记录）&quot;">​</a></h2><ul><li><strong>git 状态被干扰</strong>：开发环境后台的 Git 集成反复重置本地分支引用，常规提交失败 → 改用「提交哈希直推」方式绕过（提交对象始终安全）；</li><li><strong>工作区文件被清理</strong>：8 个文档从工作区消失 → 从 git 恢复（教训：内容在版本库里就是「后悔药」）；</li><li><strong>提交树不完整</strong>：一次构建的提交缺失大量文件 → 用差异校验发现并重建（第 18 章回归验证的实战）；</li><li><strong>截图命名不统一</strong>：早期草稿与规范冲突 → 统一命名规范并更新；</li><li><strong>文档链接失效</strong>：章节间引用路径错误 → 批量链接校验脚本修复。</li></ul><h2 id="修正与判断" tabindex="-1">修正与判断 <a class="header-anchor" href="#修正与判断" aria-label="Permalink to &quot;修正与判断&quot;">​</a></h2><ul><li>版本管理策略：<strong>所有内容先入 git 再继续</strong>，任何阶段可回滚（可恢复设计，第 8 章）；</li><li>证据归档：实测数据、截图、运行记录全部入库，评分结论必须可回查（可信度机制）；</li><li>易变信息：价格/版本统一在 <code>docs/07</code> 维护，正文引用不复制（更新机制）；</li><li>发布流程：成块合并（squash PR），main 保持可发布状态。</li></ul><h2 id="最终结果与验收" tabindex="-1">最终结果与验收 <a class="header-anchor" href="#最终结果与验收" aria-label="Permalink to &quot;最终结果与验收&quot;">​</a></h2><ul><li>公开仓库：<code>FDogeLover/ai-agent-tutorial</code>（GitHub）；</li><li>内容：23 章目录 + 5、6 章完整正文 + 其余章节正文 + 实测数据 + 18 张截图 + 8 份界面文档 + 规范文档；</li><li>验收：每阶段按任务卡验收；发布前批量校验链接与事实分级。</li></ul><h2 id="复盘" tabindex="-1">复盘 <a class="header-anchor" href="#复盘" aria-label="Permalink to &quot;复盘&quot;">​</a></h2><ul><li>Agent 做得好的：骨架搭建、批量整理、基准执行、界面文档、评分数据整理；</li><li>人必须介入的：架构决策、每阶段验收、git 异常处置、发布决策；</li><li>可沉淀：<strong>项目规则集</strong>（<code>docs/03</code> 编辑规范 + <code>docs/04</code> 内容清单 + 链接校验脚本）——即第 16 章 Harness 六层架构的完整落地案例；</li><li>教训：项目类任务中，<strong>版本管理与备份不是可选项，是安全底线</strong>（第 8 章「后悔药」）。</li></ul><h2 id="给新手的最小版本" tabindex="-1">给新手的最小版本 <a class="header-anchor" href="#给新手的最小版本" aria-label="Permalink to &quot;给新手的最小版本&quot;">​</a></h2><p>40 分钟复现：为一个个人项目（哪怕是「家庭菜谱库」）建仓库：建目录 → 写 3 条项目规则 → 加 1 个模板 → 用 Agent 生成 2 份文档 → 提交并验证「删了能恢复」。<strong>项目搭建的关键不是代码，而是「规则 + 版本 + 验证」三条线。</strong></p>',23)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
